template <typename Ctx> inline int64_t FeedMeasureMessageBody( const Ctx & ctx, const TableNumbering & numbering, int64_t index_bits, int64_t at, const Feed & value );
template <typename Ctx> inline bool FeedSaveMessageBody( const Ctx & ctx, const TableNumbering & numbering, int64_t index_bits, TableBitWriter & w, const Feed & value );
inline bool FeedLoadMessageBody( TableBitReader & r, const TableVocabulary & vocabulary, TableReport * report, const TableNodeMap & nodes, int64_t index_bits, Feed & value );

// ---- the arena's reset hook (docs/SPEC-TABLES.md §6) ----
//
// TableWorker::Alloc is a template and cannot name a member's Reset, so
// the arena reaches it through this overload set by argument-dependent
// lookup. It is how a node born in raw arena storage comes to hold the
// declared defaults without value-initialising the whole aggregate.

inline void TableReset( Header & value ) { HeaderReset( value ); }
inline void TableReset( Chunk & value ) { ChunkReset( value ); }
inline void TableReset( Feed & value ) { FeedReset( value ); }

// ---- pointer targets: allocation and resolution (docs/SPEC-TABLES.md §2) ----
//
// A reference resolves differently in the two forms, and the CONTEXT says
// which: in the arena it is an offset; in a region it is a self-relative
// delta, so the const deref below is one add and needs no base pointer.

// Chunk is a pointer target.
inline const Chunk * ChunkAt( const TableRef & ref ) // the const form's hot path: one add, no base
{
    return ref.value != 0 ? (const Chunk *) ( (const uint8_t *) &ref + ref.value ) : NULL;
}
inline Chunk * ChunkAt( TableRef & ref )
{
    return ref.value != 0 ? (Chunk *) ( (uint8_t *) &ref + ref.value ) : NULL;
}
inline const Chunk * ChunkAt( const TableRegionCtx &, const TableRef & ref ) { return ChunkAt( ref ); }
inline const Chunk * ChunkAt( const TableArenaCtx & ctx, const TableRef & ref )
{
    return ref.value != 0 ? (const Chunk *) TableArenaAt( *ctx.arena, (uint32_t) ref.value ) : NULL;
}
// while the builder is mutable, resolve against the arena itself
inline Chunk * ChunkAt( TableArena & arena, const TableRef & ref )
{
    return ref.value != 0 ? (Chunk *) TableArenaAt( arena, (uint32_t) ref.value ) : NULL;
}
inline const Chunk * ChunkAt( const TableArena & arena, const TableRef & ref )
{
    return ref.value != 0 ? (const Chunk *) TableArenaAt( arena, (uint32_t) ref.value ) : NULL;
}
// allocate one Chunk in the arena; the slot holds the arena offset
inline Chunk * ChunkEmplace( TableWorker & worker, TableRef & slot )
{
    TableSlot<Chunk> allocated = worker.Alloc<Chunk>();
    slot = allocated.ref;
    return allocated.ptr;
}

